const lesson = {
  feedback: document.querySelector('#lesson-feedback'),
  hint: document.querySelector('#lesson-hint'),
  hintButton: document.querySelector('#toggle-hint'),
  attempts: document.querySelector('#attempt-count')
};
function renderLesson(state) {
  const hintOpen = Boolean(state.hintOpen);
  lesson.hint.hidden = !hintOpen;
  lesson.hintButton.setAttribute('aria-expanded', String(hintOpen));
  lesson.hintButton.textContent = hintOpen ? 'Hide hint' : 'Ask for a hint';
  if (state.checked) {
    const correct = state.answer === 'right';
    lesson.feedback.dataset.tone = correct ? 'good' : 'try';
    lesson.feedback.textContent = correct
      ? 'Exactly. The slope is negative, so subtracting it creates a step to the right—toward x = 3.'
      : state.answer ? 'Not quite. Compare your position (−4) with the valley floor (3), then try again.' : 'Choose a direction first; a prediction is useful even when it is uncertain.';
  } else lesson.feedback.textContent = '';
  lesson.attempts.textContent = state.attempts ? `${state.attempts} prediction ${state.attempts === 1 ? 'check' : 'checks'} saved` : '';
}
document.querySelector('#check-answer').addEventListener('click', () => {
  const answer = document.querySelector('input[name="answer"]:checked')?.value || '';
  const state = window.buildParty.getState();
  window.buildParty.patchState({ answer, checked: true, attempts: Number(state.attempts || 0) + 1 });
});
lesson.hintButton.addEventListener('click', () => {
  window.buildParty.setState('hintOpen', !window.buildParty.getState().hintOpen);
});
window.buildParty.subscribe(renderLesson);

const q = selector => document.querySelector(selector);
const controls = { start: q('#start'), rate: q('#rate'), steps: q('#steps') };
function calculate(start, rate, steps) {
  const points = [];
  let x = start;
  for (let i = 0; i <= steps; i += 1) {
    points.push({ x: Number(x.toFixed(5)), loss: Number(((x - 3) ** 2).toFixed(5)) });
    x -= rate * 2 * (x - 3);
  }
  return points;
}
function position(point) {
  const x = 42 + ((Math.max(-7, Math.min(7, point.x)) + 7) / 14) * 578;
  const y = 226 - (Math.min(64, point.loss) / 64) * 196;
  return [x, y];
}
function updateLabels() {
  q('#start-value').textContent = Number(controls.start.value).toLocaleString();
  q('#rate-value').textContent = Number(controls.rate.value).toFixed(2);
  q('#steps-value').textContent = controls.steps.value;
}
function renderLab(state) {
  updateLabels();
  const hintOpen = Boolean(state.hintOpen);
  q('#lab-hint').hidden = !hintOpen;
  q('#lab-hint-button').setAttribute('aria-expanded', String(hintOpen));
  const points = Array.isArray(state.trajectory) ? state.trajectory : [];
  const trail = q('#trail');
  if (points.length) {
    const positions = points.map(position);
    trail.innerHTML = `<polyline class="step-line" points="${positions.map(p => p.join(',')).join(' ')}"/>` + positions.map((p, i) => `<circle class="step-dot ${i === positions.length - 1 ? 'final' : ''}" cx="${p[0]}" cy="${p[1]}" r="${i === positions.length - 1 ? 7 : 5}"><title>Step ${i}: x ${points[i].x}, loss ${points[i].loss}</title></circle>`).join('');
  } else trail.innerHTML = '';
  q('#final-x').textContent = state.ran ? Number(state.resultX).toFixed(3) : '—';
  q('#final-loss').textContent = state.ran ? Number(state.resultLoss).toFixed(4) : '—';
  q('#pattern').textContent = state.ran ? state.pattern : 'Run to see';
  q('#lab-summary').textContent = state.ran ? state.summary : 'Set a recipe, then run the experiment.';
  q('#run-badge').textContent = state.ran ? `Run ${state.runs || 1} saved` : 'Ready';
  q('#run-badge').className = `badge ${state.ran ? 'done' : ''}`;
}
Object.values(controls).forEach(control => control.addEventListener('input', () => {
  updateLabels();
  q('#run-badge').textContent = 'Recipe changed';
  q('#run-badge').className = 'badge dirty';
}));
q('#run').addEventListener('click', () => {
  const start = Number(controls.start.value);
  const rate = Number(controls.rate.value);
  const steps = Number(controls.steps.value);
  const trajectory = calculate(start, rate, steps);
  const last = trajectory[trajectory.length - 1];
  const jumps = trajectory.slice(1).filter((point, i) => Math.sign(point.x - 3) !== Math.sign(trajectory[i].x - 3)).length;
  const pattern = last.loss < 0.01 ? 'Converged' : jumps > 2 ? 'Bouncing' : last.loss < trajectory[0].loss ? 'Approaching' : 'Diverging';
  const summary = pattern === 'Converged' ? 'The steps shrink near the floor: the slope gets smaller as x approaches 3.' : pattern === 'Bouncing' ? 'The rate overshoots the floor repeatedly. Try a smaller η and compare.' : pattern === 'Approaching' ? 'Loss is falling, but this recipe needs more steps or a slightly bolder rate.' : 'This stride is too bold for the curve. Lower η to regain control.';
  const current = window.buildParty.getState();
  window.buildParty.patchState({ start: String(start), rate: String(rate), steps: String(steps), trajectory, resultX: last.x, resultLoss: last.loss, pattern, summary, ran: true, runs: Number(current.runs || 0) + 1 });
});
q('#reset').addEventListener('click', () => window.buildParty.patchState({ start: '-4', rate: '0.12', steps: '8', trajectory: [], resultX: null, resultLoss: null, pattern: '', summary: '', ran: false, runs: 0 }));
q('#lab-hint-button').addEventListener('click', () => window.buildParty.setState('hintOpen', !window.buildParty.getState().hintOpen));
window.buildParty.subscribe(renderLab);

const confidenceWords = { 1: 'new', 2: 'uncertain', 3: 'forming', 4: 'solid', 5: 'ready to teach' };
const confidence = document.querySelector('#confidence');
const reflection = document.querySelector('#reflection');
const checks = ['conceptDone', 'labDone', 'explainDone'];
function currentProgress() {
  const completed = checks.filter(name => document.querySelector(`input[name="${name}"]`).checked).length;
  const hasReflection = reflection.value.trim().length >= 20 ? 1 : 0;
  return Math.round(((completed + hasReflection) / 4) * 100);
}
function updateDraftUI() {
  const level = Number(confidence.value);
  document.querySelector('#confidence-label').textContent = `${level} · ${confidenceWords[level]}`;
  const words = reflection.value.trim() ? reflection.value.trim().split(/\s+/).length : 0;
  document.querySelector('#word-count').textContent = `${words} ${words === 1 ? 'word' : 'words'}`;
}
function renderReflection(state) {
  updateDraftUI();
  const progress = Number(state.progress || 0);
  const ring = document.querySelector('#progress-ring');
  ring.style.setProperty('--progress', `${progress}%`);
  ring.setAttribute('aria-valuenow', String(progress));
  document.querySelector('#progress-number').textContent = `${progress}%`;
  document.querySelector('#progress-message').textContent = progress === 100 ? 'Notebook complete. Your reflection is ready to revisit.' : progress >= 50 ? 'Momentum! Finish with one specific reflection.' : 'One honest check is a good start.';
  document.querySelector('#save-status').textContent = state.reviewed ? '✓ Reflection marked as reviewed and shared.' : '';
  const prompt = document.querySelector('#ai-prompt');
  prompt.hidden = !state.aiPrompt;
  document.querySelector('#ai-prompt-text').textContent = state.aiPrompt || '';
}
document.querySelector('.reflection-grid').addEventListener('input', () => {
  updateDraftUI();
  window.buildParty.setState('progress', currentProgress());
});
document.querySelector('#save-reflection').addEventListener('click', () => window.buildParty.patchState({ reviewed: true, progress: currentProgress() }));
document.querySelector('#draft-prompt').addEventListener('click', () => {
  const state = window.buildParty.getState();
  const level = Number(confidence.value);
  const note = reflection.value.trim();
  const focus = level <= 2 ? 'Use a simple analogy and ask me one diagnostic question.' : level >= 4 ? 'Give me a tricky counterexample and let me reason aloud.' : 'Give me a small worked example, then ask me to predict the next step.';
  const context = note ? ` My current reflection is: “${note.slice(0, 180)}${note.length > 180 ? '…' : ''}”` : ' I have not written a reflection yet, so begin by helping me name what is unclear.';
  window.buildParty.patchState({ aiPrompt: `Help me deepen my understanding of gradient descent. ${focus}${context}`, promptDrafts: Number(state.promptDrafts || 0) + 1, progress: currentProgress() });
});
window.buildParty.subscribe(renderReflection);
